//! The package runtime's C header, generated by cbindgen from the Rust
//! definitions (`editor-package-runtime`), and the test that fails when
//! the checked-in header, `crates/editor-package-runtime/include/editor_package_runtime.h`,
//! differs from it (`tests/header.rs`).
//!
//! `build.rs` runs cbindgen as a library over the definitions' one source
//! file with `cbindgen.toml`, and writes the header into `OUT_DIR` alone:
//! the build never writes into the tree. To regenerate the checked-in
//! header after a change to the definitions, copy [`GENERATED_AT`] over it;
//! the drift test's failure names both paths.
//!
//! Nothing depends on this crate (`deny.toml`), so cbindgen and its
//! dependencies are compiled for this crate's build alone, never into the
//! editor or a package's library.

/// The header cbindgen generates from the definitions.
pub const GENERATED: &str = include_str!(concat!(env!("OUT_DIR"), "/editor_package_runtime.h"));

/// Where the build wrote [`GENERATED`]: the file to copy over the
/// checked-in header.
pub const GENERATED_AT: &str = concat!(env!("OUT_DIR"), "/editor_package_runtime.h");
